// Checks the port's file format against the original Java: each saved file input-*.rec in
// golden/rec (randomly generated by the port) and golden/handwritten (edge cases) was loaded into
// the Java TableManager and saved again by scripts/golden/data.sh, as java-*.rec if that differs
// from the input.  The port must load the files and save them exactly as Java did, or fail as
// Java did (a java-*.rec file starting "!ExceptionName: message").
//
// With GENERATE_REC_INPUTS=1, this instead generates the input files (as data.sh does).
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import { CellPosition } from "../../../src/engine/data/data/CellPosition.js";
import { GridComment } from "../../../src/engine/data/data/GridComment.js";
import { SaveTag } from "../../../src/engine/identifiers/id/SaveTag.js";
import { JavaRandom } from "../../../src/engine/java/JavaRandom.js";
import { Either } from "../../../src/engine/utility-adt/utility/adt/Either.js";
import type { Value } from "../../../src/engine/utility/utility/Value.js";
import { GeometricDistribution, SimpleGenerationStatus, SourceOfRandomness } from "../../support/quickcheck.js";
import { TBasicUtil } from "../tests-basic/fixtures/data/TBasicUtil.js";
import { DummyManager } from "../tests-functions/fixtures/DummyManager.js";
import { TTableUtil } from "../tests-tables/fixtures/TTableUtil.js";
import { GenImmediateData } from "../tests-tables/fixtures/gen/GenImmediateData.js";

const DIR = fileURLToPath(new URL("./golden/rec/", import.meta.url));
const HANDWRITTEN_DIR = fileURLToPath(new URL("./golden/handwritten/", import.meta.url));
const INPUT_COUNT = 16;

// Loads and saves, giving "!ExceptionName: message" (as the Java harness does) on failure.
function loadAndSave(src: string): string
{
    try
    {
        const mgr = new DummyManager();
        mgr.loadAll(src, _w => {});
        return TTableUtil.save(mgr);
    }
    catch (e)
    {
        const t = e as Error;
        const cause = t.cause as Error | undefined;
        return "!" + t.name + ": " + t.message + (cause === undefined ? "" : " caused by " + cause.name + ": " + cause.message) + "\n";
    }
}

// Java prints the cause with its package name:
function withoutPackages(s: string): string
{
    return s.replace(/caused by (?:[a-z]+\.)+([A-Z])/, "caused by $1");
}

if (process.env.GENERATE_REC_INPUTS === "1")
{
    test("Generate input files", () =>
    {
        mkdirSync(DIR, { recursive: true });
        for (let seed = 1; seed <= INPUT_COUNT; seed++)
        {
            const r = new JavaRandom(BigInt(seed));
            const sourceOfRandomness = new SourceOfRandomness(r);
            const gs = new SimpleGenerationStatus(new GeometricDistribution(), sourceOfRandomness, seed % 10);
            const original = new GenImmediateData({ numTables: { maxTables: 4 }, canHaveErrorValues: seed % 3 === 0 }).generate(sourceOfRandomness, gs);
            // As PropLoadSaveData.testImmediateInclError, on some files:
            for (let i = 0; seed % 2 === 0 && i < 20; i++)
            {
                const table = original.data[r.nextInt(original.data.length)]!;
                if (table.getData().getLength() > 0)
                {
                    const row = r.nextInt(table.getData().getLength());
                    const column = table.getData().getColumns()[r.nextInt(table.getData().getColumns().length)]!;
                    column.getType().setCollapsed(row, Either.left<string, Value>(r.nextInt(10) === 1 ? "@END" : ("@" + r.nextInt())));
                }
            }
            // As PropLoadSaveData.testImmediate:
            let next = 1;
            for (const comment of TBasicUtil.makeList(sourceOfRandomness, 0, 5, () =>
            {
                const content = Array.from({ length: r.nextInt(3) }, () => TBasicUtil.generateColumnIds(sourceOfRandomness, r.nextInt(12)).map(c => c.getRaw()).join(" ")).join("\n");
                return new GridComment(SaveTag.generateRandom(), content, new CellPosition(r.nextInt(100), next++ * 1000), 1 + r.nextInt(20), 1 + r.nextInt(20));
            }))
                original.mgr.addComment(comment);
            if (seed % 4 === 1)
                original.mgr.addComment(new GridComment(SaveTag.generateRandom(), "Quote \" backslash \\ caret ^ at @END, new\nline,\ttab and é\u{1F600}.", new CellPosition(3, 7), 2, 3));
            writeFileSync(DIR + "input-" + String(seed).padStart(2, "0") + ".rec", TTableUtil.save(original.mgr));
        }
    }, 120_000);
}
else
{
    const inputs = [
        ...readdirSync(DIR).filter(f => f.startsWith("input-")).sort().map(f => DIR + f),
        ...readdirSync(HANDWRITTEN_DIR).filter(f => f.startsWith("input-")).sort().map(f => HANDWRITTEN_DIR + f),
    ];

    describe("Loading and saving .rec files matches Java", () =>
    {
        test("There are input files", () =>
        {
            expect(inputs.filter(f => f.startsWith(DIR)).length).toBe(INPUT_COUNT);
        });

        test.each(inputs.map(f => [f.substring(f.lastIndexOf("/golden/") + "/golden/".length), f]))("%s", (_name, input) =>
        {
            const inputSrc = readFileSync(input, "utf8");
            const javaFile = input.replace(/input-([^/]*)$/, "java-$1");
            const javaSaved = existsSync(javaFile) ? withoutPackages(readFileSync(javaFile, "utf8")) : inputSrc;
            // The port saves the input as Java did (or fails as Java did):
            expect(loadAndSave(inputSrc)).toBe(javaSaved);
            // The port reads the file saved by Java, and saves it unchanged:
            if (!javaSaved.startsWith("!"))
                expect(loadAndSave(javaSaved)).toBe(javaSaved);
        });
    });
}
